REPO_ROOT = Path(__file__).resolve().parents[3]
SANITY_SCRIPT = REPO_ROOT / "skills/surf/scripts/webgpt-tab-id-background-sanity.sh"


def test_tab_id_background_sanity_passes_js_code_before_flags(tmp_path: Path) -> None:
    invocation_log = tmp_path / "invocations.jsonl"
    fake_run = tmp_path / "surf-run.sh"
    fake_run.write_text(
        f"""#!/usr/bin/env bash
set -euo pipefail
python3 - "$@" <<'PY'
import json, pathlib, sys
pathlib.Path({str(invocation_log)!r}).open("a", encoding="utf-8").write(json.dumps(sys.argv[1:]) + "\\n")
PY
case "${{1:-}}" in
  focus.state)
    printf '{{"focusedWindowId":1,"activeTabId":111}}\\n'
    ;;
  js)
    if [[ "${{2:-}}" != return* || "${{3:-}}" != "--tab-id" ]]; then
      echo "js code must precede flags" >&2
      exit 5
    fi
    printf '{{"title":"ChatGPT","url":"https://chatgpt.com/","host":"chatgpt.com"}}\\n'
    ;;
  click)
    printf 'OK\\n'
    ;;
  *)
    echo "unexpected command: $*" >&2
    exit 9
    ;;
esac
""",
        encoding="utf-8",
    )
    fake_run.chmod(0o755)
    output_dir = tmp_path / "out"
    env = os.environ.copy()
    env["SURF_RUN_SH"] = str(fake_run)

    proc = subprocess.run(
        [
            "bash",
            str(SANITY_SCRIPT),
            "--tab-id",
            "837362205",
            "--output-dir",
            str(output_dir),
            "--json",
        ],
        cwd=tmp_path,
        env=env,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
    )

    assert proc.returncode == 0, proc.stderr
    payload = json.loads(proc.stdout)
    assert payload["status"] == "pass"
    invocations = [
        json.loads(line)
        for line in invocation_log.read_text(encoding="utf-8").splitlines()
    ]
    js_invocation = next(args for args in invocations if args[0] == "js")
    assert js_invocation[1].startswith("return JSON.stringify")
    assert js_invocation[2:4] == ["--tab-id", "837362205"]


